#define N 5
#define MAX_MOVES 5

int grid[N][N];
int scores[5];
int best;

int bonus;
int current_score;

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

void copy_grid(int src[N][N], int dst[N][N]) {
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            dst[i][j] = src[i][j];
}

int process_board(int board[N][N], int *score_out, int *bonus_out) {
    int score = 0;
    int b = *bonus_out;
    int changed = 1;
    int temp[N][N];
    int removed[N][N];

    while (changed) {
        changed = 0;
        memset(removed, 0, sizeof(removed));

        // Check horizontal matches
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N - 2; j++) {
                if (board[i][j] != -1 && board[i][j] == board[i][j+1] && board[i][j] == board[i][j+2]) {
                    int len = 3;
                    while (j + len < N && board[i][j] == board[i][j+len]) len++;
                    for (int k = 0; k < len; k++) removed[i][j+k] = 1;
                    changed = 1;
                }
            }
        }

        // Check vertical matches
        for (int j = 0; j < N; j++) {
            for (int i = 0; i < N - 2; i++) {
                if (board[i][j] != -1 && board[i][j] == board[i+1][j] && board[i][j] == board[i+2][j]) {
                    int len = 3;
                    while (i + len < N && board[i][j] == board[i+len][j]) len++;
                    for (int k = 0; k < len; k++) removed[i+k][j] = 1;
                    changed = 1;
                }
            }
        }

        if (changed) {
            // Remove matched blocks and add score
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (removed[i][j]) {
                        score += scores[board[i][j]] * b;
                        board[i][j] = -1;
                    }
                }
            }
            b++;

            // Fall down
            for (int j = 0; j < N; j++) {
                int write = N - 1;
                for (int i = N - 1; i >= 0; i--) {
                    if (board[i][j] != -1) {
                        board[write--][j] = board[i][j];
                    }
                }
                for (int i = write; i >= 0; i--) {
                    board[i][j] = -1;
                }
            }
        }
    }

    *score_out = score;
    *bonus_out = b;
    return changed;
}

void dfs(int board[N][N], int moves_left, int bonus_val) {
    int temp[N][N];
    copy_grid(board, temp);
    int add_score = 0;
    int new_bonus = bonus_val;
    process_board(temp, &add_score, &new_bonus);
    int total = current_score + add_score;

    if (total > best) best = total;

    if (moves_left == 0) return;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            // Move right
            if (j + 1 < N) {
                int new_board[N][N];
                copy_grid(board, new_board);
                swap(&new_board[i][j], &new_board[i][j+1]);

                int saved_score = current_score;
                int saved_bonus = bonus_val;

                int add = 0;
                int nb = bonus_val;
                process_board(new_board, &add, &nb);
                current_score += add;
                bonus_val = nb;

                dfs(new_board, moves_left - 1, bonus_val);

                current_score = saved_score;
                bonus_val = saved_bonus;
            }
            // Move down
            if (i + 1 < N) {
                int new_board[N][N];
                copy_grid(board, new_board);
                swap(&new_board[i][j], &new_board[i+1][j]);

                int saved_score = current_score;
                int saved_bonus = bonus_val;

                int add = 0;
                int nb = bonus_val;
                process_board(new_board, &add, &nb);
                current_score += add;
                bonus_val = nb;

                dfs(new_board, moves_left - 1, bonus_val);

                current_score = saved_score;
                bonus_val = saved_bonus;
            }
        }
    }
}

