int check_remove(int grid[5][5], int score_arr[5][5], int *score, int bonus) {
    int remove[5][5] = {0};
    int found = 0;
    for (int r = 0; r < 5; r++) for (int c = 0; c <= 2; c++) {
        if (grid[r][c] && grid[r][c]==grid[r][c+1] && grid[r][c]==grid[r][c+2]) {
