            for(int k=0;k<len;k++) remove[r+k][c]=1; found=1;
        }
    }
    if (!found) return 0;
    for (int r=0;r<5;r++) for(int c=0;c<5;c++) if(remove[r][c]) { *score += score_arr[r][c]*bonus; grid[r][c]=0; }
