int maxMoves;
int value[6];
int board0[N][N];
int best = 0;

int dr[4] = {-1, 1, 0, 0};
int dc[4] = {0, 0, -1, 1};

static inline int inside(int r, int c) {
    return r >= 0 && r < N && c >= 0 && c < N;
}

int simulate(int b[N][N]) {
    int score = 0;
    int bonus = 1;

    while (1) {
        int mark[N][N];
        memset(mark, 0, sizeof(mark));
        int any = 0;

        // Horizontal matches
        for (int r = 0; r < N; r++) {
            int c = 0;
            while (c < N) {
                if (b[r][c] == 0) {
                    c++;
                    continue;
                }
                int t = b[r][c];
                int start = c;
                while (c < N && b[r][c] == t) c++;
                if (c - start >= 3) {
                    any = 1;
                    for (int k = start; k < c; k++) mark[r][k] = 1;
                }
            }
        }

        // Vertical matches
        for (int c = 0; c < N; c++) {
            int r = 0;
            while (r < N) {
                if (b[r][c] == 0) {
                    r++;
                    continue;
                }
                int t = b[r][c];
                int start = r;
                while (r < N && b[r][c] == t) r++;
                if (r - start >= 3) {
                    any = 1;
                    for (int k = start; k < r; k++) mark[k][c] = 1;
                }
            }
        }

        if (!any) break;

        // Remove and score
        for (int r = 0; r < N; r++) {
            for (int c = 0; c < N; c++) {
                if (mark[r][c]) {
                    score += value[b[r][c]] * bonus;
                    b[r][c] = 0;
                }
            }
        }

        // Gravity
        for (int c = 0; c < N; c++) {
            int write = N - 1;
            for (int r = N - 1; r >= 0; r--) {
                if (b[r][c] != 0) {
                    b[write][c] = b[r][c];
                    if (write != r) b[r][c] = 0;
                    write--;
                }
            }
            while (write >= 0) {
                b[write][c] = 0;
                write--;
            }
        }

        bonus++;
    }

    return score;
}

void dfs(int sr, int sc, int step, int b[N][N]) {
    int temp[N][N];
    memcpy(temp, b, sizeof(temp));
    int gained = simulate(temp);
    if (gained > best) best = gained;

    if (step == maxMoves) return;

    for (int d = 0; d < 4; d++) {
        int nr = sr + dr[d];
        int nc = sc + dc[d];
        if (!inside(nr, nc)) continue;

        int nb[N][N];
        memcpy(nb, b, sizeof(nb));
        int t = nb[sr][sc];
        nb[sr][sc] = nb[nr][nc];
        nb[nr][nc] = t;

        dfs(nr, nc, step + 1, nb);
    }
}

