struct Block {
    int type;
    int score;
};

int n, maxScore;
Block grid[5][5];
int bonus;
int dx[] = {0, 0, 1, -1};
int dy[] = {1, -1, 0, 0};

int simulate(Block g[5][5], int startBonus) {
    int totalScore = 0;
    int currentBonus = startBonus;
    bool changed = true;

    while (changed) {
        changed = false;
        bool marked[5][5] = {false};

        // Check horizontal matches
        for (int i = 0; i < 5; i++) {
            for (int j = 0; j < 3; j++) {
                if (g[i][j].type == 0) continue;
                if (g[i][j].type == g[i][j+1].type && g[i][j].type == g[i][j+2].type) {
                    marked[i][j] = true;
                    marked[i][j+1] = true;
                    marked[i][j+2] = true;
                }
            }
        }

        // Check vertical matches
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 5; j++) {
                if (g[i][j].type == 0) continue;
                if (g[i][j].type == g[i+1][j].type && g[i][j].type == g[i+2][j].type) {
                    marked[i][j] = true;
                    marked[i+1][j] = true;
                    marked[i+2][j] = true;
                }
            }
        }

        // Remove marked blocks and add score
        bool removed = false;
        for (int i = 0; i < 5; i++) {
            for (int j = 0; j < 5; j++) {
                if (marked[i][j]) {
                    totalScore += g[i][j].score * currentBonus;
                    g[i][j].type = 0;
                    g[i][j].score = 0;
                    removed = true;
                }
            }
        }

        if (removed) {
            changed = true;
            // Gravity
            for (int j = 0; j < 5; j++) {
                int writeRow = 4;
                for (int i = 4; i >= 0; i--) {
                    if (g[i][j].type != 0) {
                        if (i != writeRow) {
                            g[writeRow][j] = g[i][j];
                            g[i][j].type = 0;
                            g[i][j].score = 0;
                        }
                        writeRow--;
                    }
                }
            }
            currentBonus++;
        }
    }

    return totalScore;
}

void dfs(int x, int y, int movesLeft, Block currentGrid[5][5], int startBonus) {
    if (movesLeft == 0) {
        Block temp[5][5];
        memcpy(temp, currentGrid, sizeof(Block) * 5 * 5);
        int score = simulate(temp, startBonus);
        maxScore = max(maxScore, score);
        return;
    }

    // Try moving in all directions
    for (int dir = 0; dir < 4; dir++) {
        int nx = x + dx[dir];
        int ny = y + dy[dir];

        if (nx >= 0 && nx < 5 && ny >= 0 && ny < 5) {
            // Swap
            swap(currentGrid[x][y], currentGrid[nx][ny]);

            // Check if this move creates matches
            Block temp[5][5];
            memcpy(temp, currentGrid, sizeof(Block) * 5 * 5);
            int score = simulate(temp, startBonus);
            maxScore = max(maxScore, score);

            // Continue DFS with remaining moves
            dfs(nx, ny, movesLeft - 1, currentGrid, startBonus);

            // Swap back
            swap(currentGrid[x][y], currentGrid[nx][ny]);
        }
    }
}

