#include <bits/stdc++.h>
using namespace std;

struct State {
    int a[5][5];
};

int scoreVal[6];
int nMoves;
int bestAns = 0;

inline bool inb(int r, int c) {
    return 0 <= r && r < 5 && 0 <= c && c < 5;
}

int resolveBoard(State &st) {
    int bonus = 1;
    int gained = 0;

    while (true) {
        bool mark[5][5] = {};
        bool any = false;

        // Horizontal matches
        for (int r = 0; r < 5; ++r) {
            int c = 0;
            while (c < 5) {
                if (st.a[r][c] == 0) {
                    ++c;
                    continue;
                }
                int d = c + 1;
                while (d < 5 && st.a[r][d] == st.a[r][c]) ++d;
                if (d - c >= 3) {
                    any = true;
                    for (int k = c; k < d; ++k) mark[r][k] = true;
                }
                c = d;
            }
        }

        // Vertical matches
        for (int c = 0; c < 5; ++c) {
            int r = 0;
            while (r < 5) {
                if (st.a[r][c] == 0) {
                    ++r;
                    continue;
                }
                int d = r + 1;
                while (d < 5 && st.a[d][c] == st.a[r][c]) ++d;
                if (d - r >= 3) {
                    any = true;
                    for (int k = r; k < d; ++k) mark[k][c] = true;
                }
                r = d;
            }
        }

        if (!any) break;

        // Remove and score
        for (int r = 0; r < 5; ++r) {
            for (int c = 0; c < 5; ++c) {
                if (mark[r][c]) {
                    gained += scoreVal[st.a[r][c]] * bonus;
                    st.a[r][c] = 0;
                }
            }
        }

        // Gravity
        for (int c = 0; c < 5; ++c) {
            int write = 4;
            for (int r = 4; r >= 0; --r) {
                if (st.a[r][c] != 0) {
                    st.a[write][c] = st.a[r][c];
                    if (write != r) st.a[r][c] = 0;
                    --write;
                }
            }
            while (write >= 0) {
                st.a[write][c] = 0;
                --write;
            }
        }

        bonus++;
    }

    return gained;
}

void dfs(State st, int x, int y, int used) {
    State cur = st;
    int gained = resolveBoard(cur);
    bestAns = max(bestAns, gained);

    if (used == nMoves) return;

    static int dr[4] = {-1, 1, 0, 0};
    static int dc[4] = {0, 0, -1, 1};

    for (int dir = 0; dir < 4; ++dir) {
        int nx = x + dr[dir], ny = y + dc[dir];
        if (!inb(nx, ny)) continue;
        State nxt = st; // move based on current board before resolving
        swap(nxt.a[x][y], nxt.a[nx][ny]);
        dfs(nxt, nx, ny, used + 1);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    for (int i = 1; i <= 5; ++i) cin >> scoreVal[i];
    cin >> nMoves;

    State init;
    for (int i = 0; i < 5; ++i)
        for (int j = 0; j < 5; ++j)
            cin >> init.a[i][j];

