    for (int i = 0; i < 5; ++i) {
        for (int j = 0; j < 5; ++j) {
            dfs(init, i, j, 0);
        }
    }

    cout << bestAns << '\n';
    return 0;
}

import java.util.*;

public class Main {
    static final int N = 5;
    static final int[] dx = {0, 0, 1, -1};
    static final int[] dy = {1, -1, 0, 0};
    static int maxScore = 0;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] grid = new int[N][N];
        int[] scores = new int[6]; // 1-indexed block types

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                grid[i][j] = sc.nextInt();
            }
        }
        for (int i = 1; i <= 5; i++) {
            scores[i] = sc.nextInt();
        }
        int n = sc.nextInt();

        // Try all possible starting blocks and all sequences of moves up to n
        for (int x = 0; x < N; x++) {
            for (int y = 0; y < N; y++) {
                int[][] board = deepCopy(grid);
                simulate(board, scores, x, y, n, 0, 1);
            }
        }

        System.out.println(maxScore);
        sc.close();
    }

    static void simulate(int[][] board, int[] scores, int x, int y, int movesLeft, int currentScore, int bonus) {
        // Try all possible moves from current position
        if (movesLeft > 0) {
            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx[dir];
                int ny = y + dy[dir];
                if (nx >= 0 && nx < N && ny >= 0 && ny < N) {
                    int[][] newBoard = deepCopy(board);
                    // Swap
                    int temp = newBoard[x][y];
                    newBoard[x][y] = newBoard[nx][ny];
                    newBoard[nx][ny] = temp;

                    // Process board after swap
                    int[] result = processBoard(newBoard, scores, bonus);
                    int gainedScore = result[0];
                    int newBonus = result[1];
                    int[][] processedBoard = deepCopy(newBoard); // board after all chain reactions

                    // After processing, the block we moved is now at (nx, ny)
                    // Continue simulation from that position
                    simulate(processedBoard, scores, nx, ny, movesLeft - 1, currentScore + gainedScore, newBonus);
                }
            }
        } else {
            // No moves left, update max score
            maxScore = Math.max(maxScore, currentScore);
        }
    }

    // Process board: remove matches, apply gravity, repeat until stable
    // Returns array: [scoreGained, newBonus]
    static int[] processBoard(int[][] board, int[] scores, int bonus) {
        int totalScore = 0;
        int currentBonus = bonus;

        while (true) {
            Set<String> toRemove = new HashSet<>();
            // Check horizontal matches
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (board[i][j] == 0) continue;
                    int type = board[i][j];
                    // Check horizontal line of 3+
                    int count = 1;
                    while (j + count < N && board[i][j + count] == type) count++;
                    if (count >= 3) {
                        for (int k = 0; k < count; k++) {
                            toRemove.add(i + "," + (j + k));
                        }
                    }
                    // Check vertical line of 3+
                    count = 1;
                    while (i + count < N && board[i + count][j] == type) count++;
                    if (count >= 3) {
                        for (int k = 0; k < count; k++) {
                            toRemove.add((i + k) + "," + j);
                        }
                    }
                }
            }

            if (toRemove.isEmpty()) break;

            // Remove blocks and add score
            for (String pos : toRemove) {
                String[] parts = pos.split(",");
                int r = Integer.parseInt(parts[0]);
                int c = Integer.parseInt(parts[1]);
                int type = board[r][c];
                if (type != 0) {
                    totalScore += scores[type] * currentBonus;
                    board[r][c] = 0;
                }
            }

            // Apply gravity
            applyGravity(board);
            currentBonus++;
        }

        return new int[]{totalScore, currentBonus};
    }

    static void applyGravity(int[][] board) {
        for (int c = 0; c < N; c++) {
            int writeRow = N - 1;
            for (int r = N - 1; r >= 0; r--) {
                if (board[r][c] != 0) {
                    board[writeRow][c] = board[r][c];
                    if (writeRow != r) board[r][c] = 0;
                    writeRow--;
                }
            }
            // Fill remaining with 0 (already done by shifting)
            for (int r = writeRow; r >= 0; r--) {
                board[r][c] = 0;
            }
        }
    }

    static int[][] deepCopy(int[][] original) {
        int[][] copy = new int[N][N];
        for (int i = 0; i < N; i++) {
            copy[i] = original[i].clone();
        }
        return copy;
    }
}

