public class Main {
    static int[] blockScores;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] grid = new int[5][5];
        blockScores = new int[6]; // 1-indexed block types
        for (int i = 0; i < 5; i++)
            for (int j = 0; j < 5; j++)
                grid[i][j] = sc.nextInt();
        for (int i = 1; i <= 5; i++)
            blockScores[i] = sc.nextInt();

        int maxScore = 0;
        // Try each starting block
        for (int si = 0; si < 5; si++) {
            for (int sj = 0; sj < 5; sj++) {
                // BFS/DFS over paths of up to n moves
                // State: current grid, current position of chosen block, moves remaining
                // But grid changes with each move... wait, moves just swap
                // We need to track board state through moves
                int result = dfsMove(grid, si, sj, n);
                maxScore = Math.max(maxScore, result);
            }
        }
        System.out.println(maxScore);
    }

    static int dfsMove(int[][] origGrid, int si, int sj, int n) {
        // Try all paths from (si,sj) with up to n moves
        int max = 0;
        // Use iterative DFS with state (grid copy, ci, cj, movesLeft)
        int[][][] startGrid = new int[5][5][1];
        // Use stack
        Deque<Object[]> stack = new ArrayDeque<>();
        stack.push(new Object[]{copyGrid(origGrid), si, sj, n});
        // Also evaluate at 0 moves
        max = Math.max(max, simulate(copyGrid(origGrid)));
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        while (!stack.isEmpty()) {
            Object[] top = stack.pop();
            int[][] g = (int[][]) top[0];
            int ci = (int) top[1], cj = (int) top[2], rem = (int) top[3];
            // Try each direction
            for (int[] d : dirs) {
                int ni = ci + d[0], nj = cj + d[1];
                if (ni < 0 || ni >= 5 || nj < 0 || nj >= 5) continue;
                int[][] ng = copyGrid(g);
                // Swap (ci,cj) and (ni,nj)
                int tmp = ng[ci][cj]; ng[ci][cj] = ng[ni][nj]; ng[ni][nj] = tmp;
                int score = simulate(ng);
                max = Math.max(max, score);
                if (rem > 1) {
                    stack.push(new Object[]{ng, ni, nj, rem - 1});
                }
            }
        }
        return max;
    }

    static int[][] copyGrid(int[][] g) {
        int[][] c = new int[5][5];
        for (int i = 0; i < 5; i++) c[i] = g[i].clone();
        return c;
    }

    static int simulate(int[][] grid) {
        int totalScore = 0;
        int bonus = 1;
        while (true) {
            Set<int[]> toRemove = findMatches(grid);
            if (toRemove.isEmpty()) break;
            for (int[] pos : toRemove) totalScore += blockScores[grid[pos[0]][pos[1]]] * bonus;
            for (int[] pos : toRemove) grid[pos[0]][pos[1]] = 0;
            applyGravity(grid);
            bonus++;
        }
        return totalScore;
    }

    static Set<int[]> findMatches(int[][] grid) {
        boolean[][] marked = new boolean[5][5];
        for (int i = 0; i < 5; i++) {
            for (int j = 0; j <= 2; j++) {
                if (grid[i][j] != 0 && grid[i][j] == grid[i][j+1] && grid[i][j] == grid[i][j+2])
                    for (int k = j; k < 5 && grid[i][k] == grid[i][j]; k++) marked[i][k] = true;
            }
            for (int j = 0; j <= 2; j++) {
                if (grid[j][i] != 0 && grid[j][i] == grid[j+1][i] && grid[j][i] == grid[j+2][i])
                    for (int k = j; k < 5 && grid[k][i] == grid[j][i]; k++) marked[k][i] = true;
            }
        }
        Set<int[]> res = new HashSet<>();
        for (int i = 0; i < 5; i++) for (int j = 0; j < 5; j++) if (marked[i][j]) res.add(new int[]{i,j});
        return res;
    }

    static void applyGravity(int[][] grid) {
        for (int j = 0; j < 5; j++) {
            int empty = 4;
            for (int i = 4; i >= 0; i--) {
                if (grid[i][j] != 0) { grid[empty][j] = grid[i][j]; if (empty != i) grid[i][j] = 0; empty--; }
            }
            while (empty >= 0) { grid[empty][j] = 0; empty--; }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int H = 5, W = 5;

    static int n;
    static int[] value = new int[6]; // block types 1..5
    static int[][] initial = new int[H][W];
    static int answer = 0;

    static class State {
        int[][] board;
        int r, c;      // current position of the chosen block
        int moves;     // moves used

        State(int[][] b, int r, int c, int moves) {
            this.board = b;
            this.r = r;
            this.c = c;
            this.moves = moves;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        n = fs.nextInt();
        for (int i = 1; i <= 5; i++) value[i] = fs.nextInt();
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                initial[i][j] = fs.nextInt();
            }
        }

        // Choose starting block and perform DFS of swaps up to n times.
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                int[][] b = copyBoard(initial);
                dfs(b, i, j, 0);
            }
        }

        System.out.println(answer);
    }

    static void dfs(int[][] board, int r, int c, int moves) {
        // We may stop at any time with <= n moves.
        answer = Math.max(answer, simulate(board));

        if (moves == n) return;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;

            int[][] nb = copyBoard(board);
            int tmp = nb[r][c];
            nb[r][c] = nb[nr][nc];
            nb[nr][nc] = tmp;

            dfs(nb, nr, nc, moves + 1);
        }
    }

    static int simulate(int[][] src) {
        int[][] board = copyBoard(src);
        int bonus = 1;
        int total = 0;

        while (true) {
            boolean[][] mark = new boolean[H][W];
            boolean any = false;

            // Horizontal matches
            for (int i = 0; i < H; i++) {
                int j = 0;
                while (j < W) {
                    if (board[i][j] == 0) {
                        j++;
                        continue;
                    }
                    int k = j + 1;
                    while (k < W && board[i][k] == board[i][j]) k++;
                    if (k - j >= 3) {
                        any = true;
                        for (int x = j; x < k; x++) mark[i][x] = true;
                    }
                    j = k;
                }
            }

            // Vertical matches
            for (int j = 0; j < W; j++) {
                int i = 0;
                while (i < H) {
                    if (board[i][j] == 0) {
                        i++;
                        continue;
                    }
                    int k = i + 1;
                    while (k < H && board[k][j] == board[i][j]) k++;
                    if (k - i >= 3) {
                        any = true;
                        for (int x = i; x < k; x++) mark[x][j] = true;
                    }
                    i = k;
                }
            }

            if (!any) break;

            // Remove and score
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (mark[i][j]) {
                        total += value[board[i][j]] * bonus;
                        board[i][j] = 0;
                    }
                }
            }

            // Gravity
            for (int j = 0; j < W; j++) {
                int write = H - 1;
                for (int i = H - 1; i >= 0; i--) {
                    if (board[i][j] != 0) {
                        board[write][j] = board[i][j];
                        if (write != i) board[i][j] = 0;
                        write--;
                    }
                }
                while (write >= 0) {
                    board[write][j] = 0;
                    write--;
                }
            }

            bonus++;
        }

        return total;
    }

    static int[][] copyBoard(int[][] b) {
        int[][] res = new int[H][W];
        for (int i = 0; i < H; i++) {
            System.arraycopy(b[i], 0, res[i], 0, W);
        }
        return res;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

