def solve():
    import sys
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx+=1
    grid = []
    scores_map = {}
    for i in range(5):
        row = []
        for j in range(5):
            t = int(input_data[idx]); idx+=1
            s = int(input_data[idx]); idx+=1
            row.append(t)
            scores_map[t] = s
        grid.append(row)

    def find_matches(g):
        to_remove = set()
        for r in range(5):
            c = 0
            while c < 5:
                t = g[r][c]
                c2 = c
                while c2 < 5 and g[r][c2] == t:
                    c2 += 1
                if c2 - c >= 3:
                    for cc in range(c, c2):
                        to_remove.add((r, cc))
                c = c2
        for c in range(5):
            r = 0
            while r < 5:
                t = g[r][c]
                r2 = r
                while r2 < 5 and g[r2][c] == t:
                    r2 += 1
                if r2 - r >= 3:
                    for rr in range(r, r2):
                        to_remove.add((rr, c))
                r = r2
        return to_remove

    def apply_gravity(g):
        for c in range(5):
            col = [g[r][c] for r in range(5) if g[r][c] != 0]
            col = [0]*(5-len(col)) + col
            for r in range(5):
                g[r][c] = col[r]

    def simulate(g):
        total = 0
        bonus = 1
        while True:
            matches = find_matches(g)
            if not matches:
                break
            sc = sum(scores_map.get(g[r][c], 0) for r,c in matches)
            total += sc * bonus
            for r,c in matches:
                g[r][c] = 0
            apply_gravity(g)
            bonus += 1
        return total

    best = 0

    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    # BFS over (grid_state, block_position, moves_used)
    # State: we track the grid as tuple, position of chosen block, moves left
    # To avoid exponential blowup, use memoization per chosen block start

    for sr in range(5):
        for sc in range(5):
            # BFS
            from collections import deque
            init_grid = tuple(tuple(row) for row in grid)
            visited = {}
            queue = deque()
            queue.append((init_grid, sr, sc, n))
            visited[(init_grid, sr, sc)] = n

            while queue:
                g_t, r, c, moves_left = queue.popleft()
                # simulate on copy
                g_copy = [list(row) for row in g_t]
                score = simulate(g_copy)
                best = max(best, score)

                if moves_left == 0:
                    continue

                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<5 and 0<=nc<5:
                        new_g = [list(row) for row in g_t]
                        new_g[r][c], new_g[nr][nc] = new_g[nr][nc], new_g[r][c]
                        new_g_t = tuple(tuple(row) for row in new_g)
                        key = (new_g_t, nr, nc)
                        if key not in visited or visited[key] < moves_left-1:
                            visited[key] = moves_left-1
                            queue.append((new_g_t, nr, nc, moves_left-1))

    print(best)

