import sys
from itertools import product

# 5x5 fixed board
H = W = 5

def find_matches(board):
    """Return a boolean 5x5 grid marking all cells that belong to any
    horizontal/vertical run of length >= 3 of the same nonzero value."""
    mark = [[False] * W for _ in range(H)]

    # Horizontal
    for r in range(H):
        c = 0
        while c < W:
            v = board[r][c]
            if v == 0:
                c += 1
                continue
            j = c + 1
            while j < W and board[r][j] == v:
                j += 1
            if j - c >= 3:
                for k in range(c, j):
                    mark[r][k] = True
            c = j

    # Vertical
    for c in range(W):
        r = 0
        while r < H:
            v = board[r][c]
            if v == 0:
                r += 1
                continue
            i = r + 1
            while i < H and board[i][c] == v:
                i += 1
            if i - r >= 3:
                for k in range(r, i):
                    mark[k][c] = True
            r = i

    return mark

def apply_gravity(board):
    """Make blocks fall down in each column."""
    for c in range(W):
        vals = []
        for r in range(H - 1, -1, -1):
            if board[r][c] != 0:
                vals.append(board[r][c])
        idx = 0
        for r in range(H - 1, -1, -1):
            if idx < len(vals):
                board[r][c] = vals[idx]
                idx += 1
            else:
                board[r][c] = 0

def simulate(board, scores):
    """Simulate all eliminations/cascades and return gained score."""
    b = [row[:] for row in board]
    bonus = 1
    total = 0

    while True:
        mark = find_matches(b)
        removed = False
        for r in range(H):
            for c in range(W):
                if mark[r][c]:
                    total += scores[b[r][c]] * bonus
                    b[r][c] = 0
                    removed = True
        if not removed:
            break
        apply_gravity(b)
        bonus += 1

    return total

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    # Expected input:
    # n
    # score[1] score[2] score[3] score[4] score[5]
    # 5 lines of 5 integers (block types 1..5)
    n = data[0]
    scores = [0] + data[1:6]
    arr = data[6:]

    board = [arr[i * W:(i + 1) * W] for i in range(H)]

    ans = 0

    # Choose starting block and up to n moves.
    # We only need to track the current position of the chosen block.
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # 0 moves is allowed
    ans = max(ans, simulate(board, scores))

    for sr in range(H):
        for sc in range(W):
            states = {(tuple(map(tuple, board)), sr, sc)}
            for _ in range(n):
                nxt = set()
                for bt, r, c in states:
                    b = [list(row) for row in bt]
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            nb = [row[:] for row in b]
                            nb[r][c], nb[nr][nc] = nb[nr][nc], nb[r][c]
                            nbt = tuple(map(tuple, nb))
                            nxt.add((nbt, nr, nc))
                states = nxt
                for bt, _, _ in states:
                    ans = max(ans, simulate([list(row) for row in bt], scores))

    print(ans)

if __name__ == "__main__":
    main()
